import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  ListOffsets Request (Version: 0) => replica_id [topics]
    replica_id => INT32
    topics => name [partitions]
      name => STRING
      partitions => partition_index timestamp max_num_offsets
        partition_index => INT32
        timestamp => INT64
        max_num_offsets => INT32
*/
export function createRequest(replica, _isolationLevel, topics) {
    return Writer.create().appendInt32(replica).appendArray(topics, (w, topic) => {
        w.appendString(topic.name, false).appendArray(topic.partitions, (w, partition) => w.appendInt32(partition.partitionIndex).appendInt64(partition.timestamp).appendInt32(1), false, false);
    }, false, false);
}
/*
  ListOffsets Response (Version: 0) => [topics]
    topics => name [partitions]
      name => STRING
      partitions => partition_index error_code [offsets]
        partition_index => INT32
        error_code => INT16
        offsets => INT64
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: 0,
        topics: reader.readArray((r, i) => ({
            name: r.readString(false),
            partitions: r.readArray((r, j) => {
                const partitionIndex = r.readInt32();
                const errorCode = r.readInt16();
                const offsets = r.readArray(r => r.readInt64(), false, false);
                if (errorCode !== 0) {
                    errors.push([`/topics/${i}/partitions/${j}`, [errorCode, null]]);
                }
                return { partitionIndex, errorCode, timestamp: -1n, offset: offsets[0] ?? -1n, leaderEpoch: -1 };
            }, false, false)
        }), false, false)
    };
    if (errors.length > 0) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(2, 0, createRequest, parseResponse, false, false);
